// SPDX-License-Identifier: GPL-2.0-or-later
// Generator for the HyperX mouse module device table.
// Usage: node scripts/openrgb/port-hyperx-mouse-devices.mjs <openrgb-root> <commit>
// Reads HyperXMouseControllerDetect.cpp and regenerates
// modules/hyperx-mouse/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'HyperXMouseController');
const detect = fs.readFileSync(path.join(family, 'HyperXMouseControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');

const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+(HYPERX[A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.HYPERX_VID == null) throw new Error('HYPERX_VID not found');
const n = (s) => constants[s.trim()] ?? Number.parseInt(s.trim(), 16);
const ANY = 'ANY';

// protocol and LED totals per handler, from the upstream RGBControllers:
// Surge 32 strip + 1 logo, FPS Pro/Core 1 logo, Dart 2, Raid 2, Haste 1.
const HANDLERS = {
  DetectHyperXPulsefireSurgeControllers: { protocol: 'surge', leds: 33 },
  DetectHyperXPulsefireFPSProControllers: { protocol: 'fps', leds: 1 },
  DetectHyperXPulsefireDartControllers: { protocol: 'dart', leds: 2 },
  DetectHyperXPulsefireRaidControllers: { protocol: 'raid', leds: 2 },
  DetectHyperXPulsefireHasteControllers: { protocol: 'haste', leds: 1 },
};

const rows = [];
const push = (name, handler, vid, pid, iface, usagePage, usage) => {
  const h = HANDLERS[handler];
  if (!h) throw new Error(`unknown handler ${handler}`);
  rows.push({ name, handler, vid, pid, protocol: h.protocol, leds: h.leds, iface, usagePage, usage });
};
const num = (tok) => (tok.startsWith('0x') ? Number.parseInt(tok.slice(2), 16) : Number.parseInt(tok, 10));
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR(?:_IPU?|_PU)?\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*(HYPERX_VID(?:_2)?)\s*,\s*([A-Z][A-Z0-9_]+)\s*,([^)]*)\)/g,
)) {
  const vid = n(m[3]);
  const pid = n(m[4]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[4]} in detector row ${m[1]}`);
  const args = m[5].split(',').map((s) => s.trim()).filter(Boolean);
  const variant = m[0].startsWith('REGISTER_HID_DETECTOR_IPU')
    ? 'IPU'
    : m[0].startsWith('REGISTER_HID_DETECTOR_PU')
      ? 'PU'
      : 'IP';
  if (args.length === 2) {
    // _IP: interface, usage page; _PU: usage page, usage (interface any)
    if (variant === 'PU') push(m[1], m[2], vid, pid, null, args[0], args[1]);
    else push(m[1], m[2], vid, pid, num(args[0]), args[1], null);
  } else if (args.length === 3) {
    // _IPU: interface, usage page, usage
    push(m[1], m[2], vid, pid, num(args[0]), args[1], args[2]);
  } else {
    throw new Error(`unexpected detector args ${JSON.stringify(args)} in row ${m[1]}`);
  }
}
// interface null = HID_INTERFACE_ANY
const ifaceNum = (r) => (r.iface == null ? 255 : r.iface);
const pageNum = (r) => num(r.usagePage);
const usageNum = (r) => (r.usage == null ? 0 : num(r.usage));
if (rows.length === 0) throw new Error('no HyperX mouse detectors parsed');
if (rows.length !== 14) throw new Error(`expected 14 detector rows, parsed ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'hyperx-mouse', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-hyperx-mouse-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::{Detector, Device};',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${ifaceNum(d)}, usage_page: 0x${pageNum(d).toString(16)}, usage: ${usageNum(d)} },`,
  ),
  '];',
  '',
  'pub const DEVICES: &[Device] = &[',
  ...rows.map(
    (d) =>
      `    Device { vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, protocol: ${JSON.stringify(d.protocol)}, leds: ${d.leds} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} HyperX mouse HID detectors`);